private static final ScopedValue<RequestContext> CTX = ScopedValue.newInstance();

void serve(Request req) {
    ScopedValue.where(CTX, RequestContext.of(req)).run(this::handle);
}

void handle() {                              // any depth below sees the binding
    RequestContext ctx = CTX.isBound() ? CTX.get() : RequestContext.EMPTY;
}

private static final ThreadLocal<RequestContext> CTX = new ThreadLocal<>();

void serve(Request req) {
    CTX.set(RequestContext.of(req));
    try { handle(); }
    finally { CTX.remove(); }   // or the value leaks into the next request
}
